// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1200, 360);

var ORANGE = '#d17a57';
var BLACK = '#000000';
var GRAY = '#909090';
var MUTED = '#b9b9b9';
var TEAL = '#9fded8';

var state = {
  viewMode: 'Clean diagram',
  hiddenUnitCount: 3,
  selectedHiddenUnit: null,
  step: 0
};

var demoSteps = [
  {
    title: 'Start with the network shape',
    narration: 'In the clean view, the shallow network has one input x, a single hidden layer, and one output y. The arrows show that x feeds every hidden unit, and every hidden unit feeds y.',
    state: { viewMode: 'Clean diagram', hiddenUnitCount: 3 }
  },
  {
    title: 'Reveal the parameters',
    narration: 'Switching to the parameter-labeled view shows that the input-to-hidden arrows use θ weights, while the hidden-to-output arrows use φ weights. Bias nodes labeled 1 supply additional learnable offsets.',
    state: { viewMode: 'Parameter labels', hiddenUnitCount: 3 }
  },
  {
    title: 'Focus on one hidden unit',
    narration: 'Click a hidden unit such as h₂ to isolate its local computation: it receives x through its own θ weight and bias through θ₂₀, then sends its activation to y through φ₂.',
    state: { viewMode: 'Parameter labels', hiddenUnitCount: 3, selectedHiddenUnit: 2 }
  },
  {
    title: 'Change the network width',
    narration: 'Move the hidden-unit slider to see that adding hidden units adds parallel hidden computations. Each new hidden unit brings new θ parameters into the hidden layer and a new φ contribution to the output.',
    state: { viewMode: 'Parameter labels', hiddenUnitCount: 5 }
  }
];

function sub(n) {
  return String(n).replace(/0/g, '₀').replace(/1/g, '₁').replace(/2/g, '₂').replace(/3/g, '₃').replace(/4/g, '₄').replace(/5/g, '₅').replace(/6/g, '₆').replace(/7/g, '₇').replace(/8/g, '₈').replace(/9/g, '₉');
}

function marker(color) {
  return draw.marker(13, 13, function (add) {
    add.path('M0,0 L13,6.5 L0,13 z').fill(color).stroke('none');
  }).ref(11.2, 6.5).orient('auto');
}

function radiusFor(n) {
  if (n <= 3) return 34;
  if (n === 4) return 29;
  if (n === 5) return 24;
  return 21;
}

function hiddenYs(n) {
  if (n === 1) return [205];
  var top = n <= 3 ? 115 : 70;
  var bottom = n <= 3 ? 295 : 320;
  var ys = [];
  for (var i = 0; i < n; i++) ys.push(top + (bottom - top) * i / (n - 1));
  return ys;
}

function pointOnCircleEdge(a, b, ra, rb) {
  var dx = b.x - a.x, dy = b.y - a.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  return {
    x1: a.x + dx / len * ra,
    y1: a.y + dy / len * ra,
    x2: b.x - dx / len * (rb + 3),
    y2: b.y - dy / len * (rb + 3)
  };
}

function edge(g, a, b, ra, rb, color, width, opacity, markerObj, label) {
  var p = pointOnCircleEdge(a, b, ra, rb);
  var ln = g.line(p.x1, p.y1, p.x2, p.y2)
    .stroke({ color: color, width: width, linecap: 'round' })
    .opacity(opacity == null ? 1 : opacity);
  ln.marker('end', markerObj);
  if (label) {
    ln.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(label, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { showPopup('Network parameter', label); });
  }
  return ln;
}

function mathText(g, txt, x, y, size, color, anchor, opacity) {
  var t = g.text(txt)
    .font({ family: 'Georgia, Times New Roman, serif', size: size, style: 'italic', anchor: anchor || 'middle' })
    .fill(color || BLACK)
    .center(x, y)
    .opacity(opacity == null ? 1 : opacity);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function plainText(g, txt, x, y, size, color, anchor, opacity) {
  var t = g.text(txt)
    .font({ family: 'Georgia, Times New Roman, serif', size: size, anchor: anchor || 'middle' })
    .fill(color || BLACK)
    .center(x, y)
    .opacity(opacity == null ? 1 : opacity);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

function node(g, id, x, y, r, label, selected, color, panelName) {
  var group = g.group();
  if (selected) {
    group.circle(r * 2.28).center(x, y).fill('#fff3ec').stroke({ color: ORANGE, width: 0 });
  }
  group.circle(r * 2).center(x, y)
    .fill('#ffffff')
    .stroke({ color: selected ? ORANGE : (color || BLACK), width: selected ? 3.2 : 2.8 });
  if (selected) {
    group.path('M' + (x + r * 0.10) + ',' + (y - r * 0.62) + ' Q' + (x + r * 0.52) + ',' + y + ' ' + (x + r * 0.10) + ',' + (y + r * 0.62))
      .fill('none').stroke({ color: TEAL, width: 5.5, linecap: 'round' }).opacity(0.85);
  }
  var size = Math.max(21, r * 1.07);
  mathText(group, label, x, y + 1, size, selected ? BLACK : BLACK);
  group.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      if (id > 0) {
        showTooltip('Hidden unit ' + label + ': its θ weights create an activation, and φ' + sub(id) + ' sends that activation to y.', e);
      } else {
        showTooltip(label + ' node', e);
      }
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      if (id > 0) {
        state.selectedHiddenUnit = id;
        render();
        showPopup('Hidden unit ' + label, 'This unit has its own input-side weights θ' + sub(id) + '₁ and θ' + sub(id) + '₀. Its activation is then combined at the output through φ' + sub(id) + '.');
      }
    });
  return group;
}

function parameterLabel(g, text, x, y, color, opacity) {
  var t = mathText(g, text, x, y, 22, color, 'middle', opacity);
  t.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(text + ' is a learnable parameter.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Learnable parameter ' + text, 'A parameter is adjusted during training. θ parameters build hidden activations from x and bias inputs; φ parameters combine hidden activations into y.'); });
  return t;
}

function drawPanelA(root, opacity) {
  var g = root.group().opacity(opacity);
  var n = state.hiddenUnitCount;
  var ys = hiddenYs(n);
  var r = radiusFor(n);
  var xNode = { x: 35, y: 205 };
  var hb = { x: 35, y: 105 };
  var ob = { x: 285, y: 45 };
  var hx = 285;
  var yNode = { x: 535, y: 205 };
  var nodeR = Math.min(34, r);
  var blackM = marker(BLACK), orangeM = marker(ORANGE), grayM = marker(MUTED);

  plainText(g, 'a)', 18, 22, 34, BLACK);

  for (var i = 0; i < n; i++) {
    var k = i + 1;
    var h = { x: hx, y: ys[i] };
    var sel = state.selectedHiddenUnit === k;
    var focus = state.selectedHiddenUnit != null;
    var xColor = sel ? ORANGE : (focus ? MUTED : BLACK);
    var bColor = sel ? ORANGE : (focus ? MUTED : ORANGE);
    var outColor = sel ? ORANGE : (focus ? MUTED : BLACK);
    edge(g, xNode, h, nodeR, r, xColor, sel ? 3.3 : 2.2, 1, sel ? orangeM : (focus ? grayM : blackM), 'θ' + sub(k) + '₁: weight from x to h' + sub(k));
    edge(g, hb, h, nodeR, r, bColor, sel ? 3.3 : 2.2, 1, sel ? orangeM : (focus ? grayM : orangeM), 'θ' + sub(k) + '₀: bias weight into h' + sub(k));
    edge(g, h, yNode, r, nodeR, outColor, sel ? 3.3 : 2.2, 1, sel ? orangeM : (focus ? grayM : blackM), 'φ' + sub(k) + ': output weight from h' + sub(k) + ' to y');
  }
  edge(g, ob, yNode, nodeR, nodeR, state.selectedHiddenUnit ? MUTED : ORANGE, 2.2, 1, state.selectedHiddenUnit ? grayM : orangeM, 'φ₀: output bias weight');

  node(g, 0, xNode.x, xNode.y, nodeR, 'x', false);
  node(g, -1, hb.x, hb.y, nodeR, '1', false, ORANGE);
  node(g, -2, ob.x, ob.y, nodeR, '1', false, ORANGE);
  for (var j = 0; j < n; j++) {
    node(g, j + 1, hx, ys[j], r, 'h' + sub(j + 1), state.selectedHiddenUnit === j + 1);
  }
  node(g, 0, yNode.x, yNode.y, nodeR, 'y', false);

  for (var a = 0; a < n; a++) {
    var kk = a + 1;
    var yy = ys[a];
    var selA = state.selectedHiddenUnit === kk;
    var focusA = state.selectedHiddenUnit != null;
    var activeIn = selA ? ORANGE : (focusA ? MUTED : GRAY);
    var activeBias = selA ? ORANGE : (focusA ? MUTED : ORANGE);
    var activePhi = selA ? ORANGE : (focusA ? MUTED : GRAY);

    var bx = 198 + (n > 3 ? 12 : 0);
    var by = hb.y + (yy - hb.y) * 0.46 - 15;
    if (n === 3 && kk === 1) by -= 7;
    parameterLabel(g, 'θ' + sub(kk) + '₀', bx, by, activeBias, 1);

    var xi = 143;
    var yi = xNode.y + (yy - xNode.y) * 0.58 + (kk === 1 ? -14 : (kk === n ? 13 : -7));
    parameterLabel(g, 'θ' + sub(kk) + '₁', xi, yi, activeIn, 1);

    var px = 405;
    var py = yy + (yNode.y - yy) * 0.34 + (kk === 1 ? -8 : (kk === n ? 9 : -12));
    parameterLabel(g, 'φ' + sub(kk), px, py, activePhi, 1);
  }
  parameterLabel(g, 'φ₀', 405, 93, state.selectedHiddenUnit ? MUTED : ORANGE, 1);
}

function drawPanelB(root, opacity) {
  var g = root.group().opacity(opacity);
  var n = state.hiddenUnitCount;
  var ys = hiddenYs(n);
  var r = radiusFor(n);
  var xNode = { x: 690, y: 205 };
  var hx = 930;
  var yNode = { x: 1160, y: 205 };
  var nodeR = Math.min(34, r);
  var blackM = marker(BLACK), orangeM = marker(ORANGE), grayM = marker(MUTED);

  plainText(g, 'b)', 665, 22, 34, BLACK);

  for (var i = 0; i < n; i++) {
    var k = i + 1;
    var h = { x: hx, y: ys[i] };
    var sel = state.selectedHiddenUnit === k;
    var focus = state.selectedHiddenUnit != null;
    var color = sel ? ORANGE : (focus ? MUTED : BLACK);
    var m = sel ? orangeM : (focus ? grayM : blackM);
    edge(g, xNode, h, nodeR, r, color, sel ? 3.3 : 2.4, 1, m, 'x feeds hidden unit h' + sub(k));
    edge(g, h, yNode, r, nodeR, color, sel ? 3.3 : 2.4, 1, m, 'h' + sub(k) + ' contributes to the output y');
  }

  node(g, 0, xNode.x, xNode.y, nodeR, 'x', false);
  for (var j = 0; j < n; j++) {
    node(g, j + 1, hx, ys[j], r, 'h' + sub(j + 1), state.selectedHiddenUnit === j + 1);
  }
  node(g, 0, yNode.x, yNode.y, nodeR, 'y', false);
}

function render() {
  draw.clear();
  if (state.selectedHiddenUnit && state.selectedHiddenUnit > state.hiddenUnitCount) state.selectedHiddenUnit = null;

  var paramOpacity = state.viewMode === 'Parameter labels' ? 1 : 0.46;
  var cleanOpacity = state.viewMode === 'Clean diagram' ? 1 : 0.46;

  drawPanelA(draw, paramOpacity);
  drawPanelB(draw, cleanOpacity);
}

function update_hiddenUnitCount(v) {
  state.hiddenUnitCount = Math.max(1, Math.min(6, Math.round(v)));
  var out = document.getElementById('hiddenUnitCountVal');
  var inp = document.getElementById('hiddenUnitCountInput');
  if (out) out.value = state.hiddenUnitCount;
  if (inp) inp.value = state.hiddenUnitCount;
  render();
}

function toggle_viewMode(on) {
  state.viewMode = on ? 'Clean diagram' : 'Parameter labels';
  var out = document.getElementById('viewModeVal');
  if (out) out.value = state.viewMode;
  render();
}

function syncControls() {
  var chk = document.getElementById('viewModeInput');
  var vm = document.getElementById('viewModeVal');
  var slider = document.getElementById('hiddenUnitCountInput');
  var hv = document.getElementById('hiddenUnitCountVal');
  if (chk) chk.checked = state.viewMode === 'Clean diagram';
  if (vm) vm.value = state.viewMode;
  if (slider) slider.value = state.hiddenUnitCount;
  if (hv) hv.value = state.hiddenUnitCount;
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.viewMode = step.state.viewMode || state.viewMode;
  state.hiddenUnitCount = step.state.hiddenUnitCount || state.hiddenUnitCount;
  state.selectedHiddenUnit = step.state.selectedHiddenUnit || null;

  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (state.step + 1) + ' / ' + demoSteps.length + ' — ' + step.title;

  syncControls();
  render();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

