<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
document.documentElement.style.setProperty('--figure-canvas-padding', '4px');

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1640, 424);
draw.attr({ preserveAspectRatio: 'xMidYMid meet' });

var BLACK = '#000000';
var ORANGE = '#d17a57';
var GRAY = '#8e8e8e';
var TEAL = '#9fded8';
var BLUE = '#2b6fc4';
var BIAS_GLOW = '#f1b08f';

var state = {
  emphasisMode: 'Original figure',
  selectedHiddenUnit: null,
  step: 0
};

var demoSteps = [
  {
    title: 'Original two-panel comparison',
    narration: 'Both source panels are visible at full opacity: panel a) shows the same three-hidden-unit network with parameter annotations, while panel b) shows the cleaner computation graph.',
    state: { emphasisMode: 'Original figure', selectedHiddenUnit: null }
  },
  {
    title: 'Input-side θ parameters',
    narration: 'The θ emphasis marks the connections that build each hidden activation from the input x and the hidden-layer bias. Nothing is removed; the emphasis is only an overlay on the original figure.',
    state: { emphasisMode: 'θ input weights', selectedHiddenUnit: null }
  },
  {
    title: 'Output-side φ parameters',
    narration: 'The φ emphasis marks the connections that combine h₁, h₂, and h₃ into the output y, including the output bias parameter φ₀.',
    state: { emphasisMode: 'φ output weights', selectedHiddenUnit: null }
  },
  {
    title: 'Follow one hidden unit',
    narration: 'The h₂ pathway is highlighted: θ₂₁ and θ₂₀ determine that hidden activation, and φ₂ determines how it contributes to y. Click any hidden unit to switch the pathway.',
    state: { emphasisMode: 'Original figure', selectedHiddenUnit: 2 }
  }
];

function sub(n) {
  return String(n)
    .replace(/0/g, '₀').replace(/1/g, '₁').replace(/2/g, '₂')
    .replace(/3/g, '₃').replace(/4/g, '₄').replace(/5/g, '₅')
    .replace(/6/g, '₆').replace(/7/g, '₇').replace(/8/g, '₈').replace(/9/g, '₉');
}

function makeMarker(color) {
  var m = draw.marker(28, 20, function (add) {
    add.path('M0,0 L26,10 L0,20 z').fill(color).stroke('none');
  });
  m.ref(24, 10).orient('auto');
  m.attr({ markerUnits: 'userSpaceOnUse', markerWidth: 28, markerHeight: 20 });
  return m;
}

function edgeEnds(a, b, ra, rb) {
  var dx = b.x - a.x;
  var dy = b.y - a.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  return {
    x1: a.x + dx / len * (ra + 2),
    y1: a.y + dy / len * (ra + 2),
    x2: b.x - dx / len * (rb + 4),
    y2: b.y - dy / len * (rb + 4)
  };
}

function shouldEmphasize(kind, hid) {
  if (state.selectedHiddenUnit === hid && hid > 0) return 'selected';
  if (state.emphasisMode === 'θ input weights' && (kind === 'thetaInput' || kind === 'thetaBias')) return 'theta';
  if (state.emphasisMode === 'φ output weights' && (kind === 'phiHidden' || kind === 'phiBias')) return 'phi';
  if (state.emphasisMode === 'Bias terms' && (kind === 'thetaBias' || kind === 'phiBias')) return 'bias';
  return null;
}

function drawEdge(g, a, b, ra, rb, color, kind, hid, tip) {
  var p = edgeEnds(a, b, ra, rb);
  var emph = shouldEmphasize(kind, hid);

  if (emph) {
    var haloColor = emph === 'phi' ? BLUE : (emph === 'theta' ? ORANGE : (emph === 'bias' ? BIAS_GLOW : ORANGE));
    g.line(p.x1, p.y1, p.x2, p.y2)
      .stroke({ color: haloColor, width: emph === 'selected' ? 14 : 12, linecap: 'round' })
      .opacity(emph === 'selected' ? 0.52 : 0.36);
  }

  var line = g.line(p.x1, p.y1, p.x2, p.y2)
    .stroke({ color: color, width: 3.6, linecap: 'round' })
    .marker('end', color === ORANGE ? arrowOrange : arrowBlack);

  if (tip) {
    line.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { showPopup('Connection', tip); });
  }
  return line;
}

function labelText(g, txt, x, y, size, color, anchor, family, style, weight) {
  var t = g.text(txt)
    .font({
      family: family || 'Georgia, Times New Roman, serif',
      size: size,
      anchor: anchor || 'middle',
      style: style || 'italic',
      weight: weight || 'normal'
    })
    .fill(color || BLACK)
    .center(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
  return t;
}

function panelLabel(g, txt, x, y) {
  return g.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 50, weight: 500, anchor: 'start' })
    .fill(BLACK)
    .move(x, y);
}

function parameterLabel(g, txt, x, y, color) {
  var t = labelText(g, txt, x, y, 36, color || GRAY, 'middle', 'Georgia, Times New Roman, serif', 'italic');
  t.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(txt + ' is a learnable network parameter.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Learnable parameter ' + txt, 'Training adjusts this weight. θ parameters build hidden activations from x and bias inputs; φ parameters combine hidden activations and the output bias into y.');
    });
  return t;
}

function drawNode(g, x, y, r, label, opts) {
  opts = opts || {};
  var group = g.group();
  var isSelected = opts.hiddenIndex && state.selectedHiddenUnit === opts.hiddenIndex;
  var isBias = opts.bias;
  var biasEmph = state.emphasisMode === 'Bias terms' && isBias;

  if (biasEmph || isSelected) {
    group.circle(r * 2.62).center(x, y)
      .fill(isSelected ? '#fff3ec' : '#fff7f0')
      .stroke({ color: isSelected ? ORANGE : BIAS_GLOW, width: isSelected ? 4 : 3 })
      .opacity(0.92);
  }

  group.circle(r * 2).center(x, y)
    .fill('#ffffff')
    .stroke({ color: isBias ? ORANGE : BLACK, width: 3.8 });

  if (opts.teal) {
    group.path('M' + (x + r * 0.38) + ',' + (y - r * 0.82) +
      ' Q' + (x + r * 0.94) + ',' + y + ' ' + (x + r * 0.38) + ',' + (y + r * 0.82))
      .fill('none')
      .stroke({ color: TEAL, width: 7.4, linecap: 'round' })
      .opacity(0.95);
  }

  labelText(group, label, x, y + 2, label.length > 1 ? 45 : 43, isBias ? ORANGE : BLACK);

  group.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      if (opts.hiddenIndex) {
        showTooltip('Hidden unit ' + label + ': one parallel feature computed from x and a bias, then sent to y.', e);
      } else if (isBias) {
        showTooltip('Bias node 1 supplies an offset parameter.', e);
      } else {
        showTooltip(label + ' node', e);
      }
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      if (opts.hiddenIndex) {
        state.selectedHiddenUnit = state.selectedHiddenUnit === opts.hiddenIndex ? null : opts.hiddenIndex;
        render();
        if (state.selectedHiddenUnit) {
          showPopup('Hidden unit ' + label, 'This hidden unit receives x through θ' + sub(opts.hiddenIndex) + '₁ and the hidden-layer bias through θ' + sub(opts.hiddenIndex) + '₀. Its activation then contributes to y through φ' + sub(opts.hiddenIndex) + '.');
        }
      } else if (isBias) {
        showPopup('Bias term', 'A bias node is fixed at 1, so its edge weight acts as an adjustable offset. Bias offsets let hidden units and the output shift without depending only on x.');
      }
    });

  return group;
}

function drawPanelA(root) {
  var g = root.group();
  panelLabel(g, 'a)', 0, -10);

  var r = 44;
  var xNode = { x: 46, y: 282 };
  var hiddenBias = { x: 46, y: 168 };
  var outputBias = { x: 392, y: 57 };
  var hidden = [
    { x: 392, y: 170, id: 1 },
    { x: 392, y: 282, id: 2 },
    { x: 392, y: 394, id: 3 }
  ];
  var yNode = { x: 738, y: 282 };

  for (var i = 0; i < hidden.length; i++) {
    var h = hidden[i];
    drawEdge(g, xNode, h, r, r, BLACK, 'thetaInput', h.id, 'θ' + sub(h.id) + '₁ carries x into hidden unit h' + sub(h.id) + '.');
    drawEdge(g, hiddenBias, h, r, r, ORANGE, 'thetaBias', h.id, 'θ' + sub(h.id) + '₀ is the bias weight for hidden unit h' + sub(h.id) + '.');
    drawEdge(g, h, yNode, r, r, BLACK, 'phiHidden', h.id, 'φ' + sub(h.id) + ' weights hidden activation h' + sub(h.id) + ' at the output.');
  }
  drawEdge(g, outputBias, yNode, r, r, ORANGE, 'phiBias', 0, 'φ₀ is the output bias weight.');

  drawNode(g, hiddenBias.x, hiddenBias.y, r, '1', { bias: true });
  drawNode(g, xNode.x, xNode.y, r, 'x');
  drawNode(g, outputBias.x, outputBias.y, r, '1', { bias: true });
  for (var j = 0; j < hidden.length; j++) {
    drawNode(g, hidden[j].x, hidden[j].y, r, 'h' + sub(hidden[j].id), { hiddenIndex: hidden[j].id, teal: true });
  }
  drawNode(g, yNode.x, yNode.y, r, 'y');

  parameterLabel(g, 'θ₁₀', 296, 132, ORANGE);
  parameterLabel(g, 'θ₂₀', 296, 224, ORANGE);
  parameterLabel(g, 'θ₃₀', 304, 333, ORANGE);

  parameterLabel(g, 'θ₁₁', 232, 202, GRAY);
  parameterLabel(g, 'θ₂₁', 232, 260, GRAY);
  parameterLabel(g, 'θ₃₁', 232, 329, GRAY);

  parameterLabel(g, 'φ₀', 548, 118, ORANGE);
  parameterLabel(g, 'φ₁', 548, 193, GRAY);
  parameterLabel(g, 'φ₂', 548, 261, GRAY);
  parameterLabel(g, 'φ₃', 548, 331, GRAY);
}

function drawPanelB(root) {
  var g = root.group();
  panelLabel(g, 'b)', 856, -10);

  var r = 44;
  var xNode = { x: 904, y: 282 };
  var hidden = [
    { x: 1252, y: 170, id: 1 },
    { x: 1252, y: 282, id: 2 },
    { x: 1252, y: 394, id: 3 }
  ];
  var yNode = { x: 1598, y: 282 };

  for (var i = 0; i < hidden.length; i++) {
    var h = hidden[i];
    drawEdge(g, xNode, h, r, r, BLACK, 'thetaInput', h.id, 'Input x feeds hidden unit h' + sub(h.id) + ' in parallel with the other hidden units.');
    drawEdge(g, h, yNode, r, r, BLACK, 'phiHidden', h.id, 'Hidden unit h' + sub(h.id) + ' contributes one weighted feature to y.');
  }

  drawNode(g, xNode.x, xNode.y, r, 'x');
  for (var j = 0; j < hidden.length; j++) {
    drawNode(g, hidden[j].x, hidden[j].y, r, 'h' + sub(hidden[j].id), { hiddenIndex: hidden[j].id });
  }
  drawNode(g, yNode.x, yNode.y, r, 'y');
}

var arrowBlack, arrowOrange;

function render() {
  draw.clear();
  arrowBlack = makeMarker(BLACK);
  arrowOrange = makeMarker(ORANGE);
  drawPanelA(draw);
  drawPanelB(draw);
}

function update_emphasisMode(v) {
  state.emphasisMode = v || 'Original figure';
  var out = document.getElementById('emphasisModeVal');
  var input = document.getElementById('emphasisModeInput');
  if (out) out.value = state.emphasisMode;
  if (input) input.value = state.emphasisMode;
  render();
}

function toggle_emphasisMode(on) {
  update_emphasisMode(on ? 'θ input weights' : 'Original figure');
}

function clearSelection() {
  state.selectedHiddenUnit = null;
  render();
}

function syncControls() {
  var out = document.getElementById('emphasisModeVal');
  var input = document.getElementById('emphasisModeInput');
  if (out) out.value = state.emphasisMode;
  if (input) input.value = state.emphasisMode;
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.emphasisMode = step.state.emphasisMode || 'Original figure';
  state.selectedHiddenUnit = step.state.selectedHiddenUnit == null ? null : step.state.selectedHiddenUnit;

  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (state.step + 1) + ' / ' + demoSteps.length + ' — ' + step.title;

  syncControls();
  render();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

